{"description":"Fetch gcsim hutao source files","command":"$base='http./'
$files=@('cons.go','skill.go','burst.go','charge.go','asc.go','hutao.go')
foreach($f in $files){
  $u="$base/$f"
  $r = curl.exe -s --max-time 30 --proxy htt./ $u
  if(-not $r -or $r -match '^404'){ $r = curl.exe -s --max-time 30 $u }
  "`n===== $f ($($r.Count) lines) ====="
  ($r -join "`n")
}"}

