{"command":"$Proxy='htt./'
$urls=@('http./','http./')
foreach($u in $urls){
  "===== $u ====="
  $raw = (curl.exe -s --max-time 25 --proxy $Proxy $u) -join ''
  if([string]::IsNullOrWhiteSpace($raw) -or $raw -match '^\s*(404|error)'){ $raw = (curl.exe -s --max-time 20 $u) -join '' }
  "len=$($raw.Length)"
  if($raw.Length -lt 50){ "FETCH_FAIL"; continue }
  $m = [regex]::Matches($raw,'"Name"\s*:\s*"([\u4e00-\u9fff][^"]{1,24})"')
  "--- CJK Names ---"
  ($m | ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique -First 40) -join ' | '
  $d = [regex]::Matches($raw,'"Desc"\s*:\s*"([^"]{8,160})"')
  "--- Descs (first 12) ---"
  ($d | ForEach-Object { $_.Groups[1].Value } | Select-Object -First 12) -join "`n"
}","description":"Probe Chinese datamine API via proxy for names"}

